'use strict';
const paths={arrow:'M5 12h14m-5-5 5 5-5 5',back:'m14 6-6 6 6 6',calendar:'M5 5h14v15H5zM8 3v4m8-4v4M5 10h14',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0ZM9 10a3 3 0 1 0 6 0 3 3 0 0 0-6 0',mountain:'m2 20 7-14 5 8 3-5 5 11H2Zm4-8 3 2 2-3',sun:'M16 10a5 5 0 1 0-7 7M12 2v2M4 5l2 2M2 12h2m15-7-2 2M9 20h10a4 4 0 1 0-1-8 5 5 0 0 0-9 8Z',users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 21v-3a7 7 0 0 1 14 0v3m1-17a4 4 0 0 1 0 7m1 4a6 6 0 0 1 4 6',bell:'M5 17h14l-2-3V9A5 5 0 0 0 7 9v5l-2 3Zm5 3h4',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM4 21a8 8 0 0 1 16 0',plus:'M12 5v14M5 12h14',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Zm5-2 6 6',check:'m5 12 5 5L20 7',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20Zm0-16v6l4 2',close:'m6 6 12 12M6 18 18 6',list:'M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1'};
const escapeAttr=s=>s.replaceAll('&','&amp;').replaceAll('\"','&quot;').replaceAll('<','&lt;');
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.arrow}"/></svg>`;
const app=document.querySelector('#app'),bottom=document.querySelector('#bottom'),modal=document.querySelector('#modal');
let page='home',homeTab='all',filter='pending',query='',submitted=false,weatherDay=0,hour=1;
const people=[{name:'陈小满',trip:'拼车 · 地铁站集合',status:'pending'},{name:'周远',trip:'自行前往 · 山脚集合',status:'pending'},{name:'林一',trip:'拼车 · 地铁站集合',status:'pending'},{name:'许言',trip:'自行前往 · 山脚集合',status:'confirmed'},{name:'王溪',trip:'拼车 · 地铁站集合',status:'confirmed'},{name:'赵可',trip:'拼车 · 地铁站集合',status:'confirmed'},{name:'沈南',trip:'自行前往 · 山脚集合',status:'waitlist'},{name:'唐安',trip:'拼车 · 地铁站集合',status:'confirmed'},{name:'方宁',trip:'自行前往 · 山脚集合',status:'confirmed'},{name:'宋晴',trip:'拼车 · 地铁站集合',status:'confirmed'},{name:'江舟',trip:'拼车 · 地铁站集合',status:'confirmed'},{name:'叶禾',trip:'自行前往 · 山脚集合',status:'confirmed'},{name:'杜川',trip:'拼车 · 地铁站集合',status:'confirmed'},{name:'李沐',trip:'拼车 · 地铁站集合',status:'confirmed'},{name:'顾青',trip:'自行前往 · 山脚集合',status:'confirmed'},{name:'陆宁',trip:'拼车 · 地铁站集合',status:'confirmed'}];
const count=s=>people.filter(p=>p.status===s).length;
const back=(to,label='返回')=>`<button class="back" data-go="${to}">${icon('back')}${label}</button>`;
const nav=(active='home')=>`<nav class="tabbar" aria-label="主要导航">${[['home','mountain','活动'],['weather','sun','天气'],['notices','bell','通知'],['me','user','我的']].map(([id,i,t])=>`<button ${id==='notices'||id==='me'?`data-sheet="${id}"`:`data-go="${id}"`} class="${active===id?'on':''}">${icon(i)}${t}</button>`).join('')}</nav>`;
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.style.display='none',2300)}
const notes={home:['从下一次同行开始','日期，是活动最自然的顺序。','Luma 式日期分组，让近期活动与自己的责任一起出现。','有重点，不做仪表盘。','只突出最近的一次同行，其余活动回到紧凑列表。'],detail:['先理解，再决定加入','让活动内容成为主角。','不依赖摄影封面。时间、集合、路线指标构成首屏的信息骨架。','主操作跟随个人状态。','报名入口始终可达；提交后变为查看报名，不误报已通过。'],signup:['一次填写，交代清楚','信息按人的任务分组。','本人信息、出行方式、紧急联系人分别组织，减少长表单的杂乱。','提交与通过是两件事。','此活动需要审核。演示提交后明确显示等待审核，不直接计入已确认。'],roster:['让名单成为工作台','状态和数量相邻。','参考 Luma 的名单组织；筛选内搜索，查看资料后处理，数量同步更新。','一个人，可以有多种状态。','审核状态与出行方式分开，自行前往不会被显示成未分车。'],weather:['把空间还给天气','图表是连续的证据。','温度和降水按相同时间排列。选择时间后更新读数，不用装饰性评分。','未知，也需要明确表达。','示例节点没有可信海拔，所以不判断云海。模拟天气不用于实际出行。']};
function render(){modal.hidden=true;document.querySelector('#wx-title').textContent=page==='home'?'OurTrail':({detail:'活动详情',signup:'活动报名',roster:'活动管理',weather:'路线天气'}[page]);document.querySelectorAll('.screen-menu button').forEach(b=>b.classList.toggle('active',b.dataset.go===page));let n=notes[page];document.querySelector('#notes').innerHTML=`<h2>${n[0]}</h2><span class="number">01 / STRUCTURE</span><p><b>${n[1]}</b><br>${n[2]}</p><span class="number">02 / INTERACTION</span><p><b>${n[3]}</b><br>${n[4]}</p>`;({home:home,detail:detail,signup:signup,roster:roster,weather:weather}[page])();app.scrollTop=0}
function go(to){if(!notes[to])return;clearTimeout(window.toastTimer);document.querySelector('#toast').style.display='none';page=to;if(location.hash!==`#${to}`)history.replaceState(null,'',`#${to}`);render()}
function home(){app.innerHTML=`<div class="pad"><div class="topline"><div><span class="sub">10 月 26 日，星期一</span><h2 class="page-title">周末，去山里。</h2></div><button class="round" aria-label="发起活动" data-sheet="create">${icon('plus')}</button></div><p class="sub">一起出发，把沿途留给彼此。</p><div class="tabs"><button data-home="all" class="${homeTab==='all'?'on':''}">全部活动</button><button data-home="joined" class="${homeTab==='joined'?'on':''}">我参与的</button><button data-home="hosted" class="${homeTab==='hosted'?'on':''}">我发起的</button></div>${homeTab!=='hosted'&&(homeTab!=='joined'||submitted)?`<div class="section-title"><h3>下一次同行</h3><span class="tiny">本周六</span></div><article class="upcoming"><button class="inner" style="text-align:left;width:100%" data-go="detail"><span class="badge">${submitted?'等待审核':'正在报名'}</span><h2>走进秋天的山野<br>龙泉山轻徒步</h2><div class="metric-line"><span>10.31 周六</span><span>08:00 集合</span></div><div class="people"><div class="avatars"><span class="avatar">阿</span><span class="avatar">许</span><span class="avatar">王</span><span class="avatar">赵</span></div><span style="margin-left:9px">8 位伙伴已确认同行</span></div></button><button class="next-action" data-go="detail"><span><b>12.6 km</b> 徒步 &nbsp; · &nbsp; 爬升 650 m</span>${icon('arrow')}</button></article>`:''}${homeTab!=='joined'?`<div class="section-title"><h3>我组织的</h3><span class="tiny">1 场活动</span></div><button class="list-row" data-go="roster"><div class="datebox">11 月<b>07</b>周六</div><div class="grow"><strong>青城后山 · 林间慢行</strong><span class="tiny">${count('confirmed')} 人已确认 · ${count('pending')} 人待审核</span></div><span class="badge amber">去处理</span></button>`:''}${homeTab==='joined'&&!submitted?'<div class="empty">还没有参与的活动<br><button class="text-btn" data-go="detail">看看本周的龙泉山同行 →</button></div>':''}<div class="section-title"><h3>${homeTab==='hosted'?'组织活动的小提醒':'再远一点的计划'}</h3></div>${homeTab==='hosted'?'<p class="body-copy">名单审核完成后，再检查大家的出行方式和集合点。自行前往的伙伴不需要分配座位。</p>':`<button class="list-row" data-sheet="later"><div class="datebox">11 月<b>14</b>周六</div><div class="grow"><strong>都江堰 · 山谷寻秋</strong><span class="tiny">阿禾发起 · 9.2 km · 爬升 420 m</span></div>${icon('arrow')}</button>`}<p class="source">熟人同行，轻装出发。</p></div>`;bottom.innerHTML=nav()}
function detail(){app.innerHTML=`<header class="detail-header">${back('home','活动')}<svg class="contours" viewBox="0 0 200 200" fill="none" stroke="#6a825b">${[0,1,2,3,4,5,6].map(i=>`<ellipse cx="130" cy="95" rx="${37+i*12}" ry="${24+i*13}" transform="rotate(-30 130 95)"/>`).join('')}</svg><div style="margin-top:14px" class="overline">周末同行 / 龙泉山</div><h1>走进秋天的山野<br>龙泉山轻徒步</h1><div class="host"><span class="avatar">禾</span><span>阿禾 发起</span><span class="tiny">· 熟人同行</span></div></header><div class="pad" style="padding-top:0"><div class="stats"><div><b>12.6</b><small>km</small><span>徒步距离</span></div><div><b>650</b><small>m</small><span>累计爬升</span></div><div><b>20</b><small>人</small><span>活动名额</span></div></div><div class="info-row">${icon('calendar')}<div><b>10 月 31 日，星期六</b><p>08:00 集合 · 预计 17:00 结束<br>10 月 29 日 20:00 报名截止</p></div></div><div class="info-row">${icon('pin')}<div><b>龙泉驿地铁站 A 口</b><p>拼车伙伴在此集合，自行前往可选山脚集合点。</p></div></div><div class="divider"></div><div class="section-title"><h3>这一次，慢慢走</h3><span class="tiny">活动介绍</span></div><p class="body-copy">沿山脊走一段，把城市留在身后。途经林间小路和开阔观景点，午间自带路餐，大家一起歇一歇。</p><button class="inline-weather" data-go="weather">${icon('sun')}<div class="grow"><strong>出发前，看一眼路线天气</strong><span class="tiny">按节点查看温度、降水与风</span></div>${icon('arrow')}</button><div class="section-title"><h3>行前准备</h3></div><div class="pill-list"><span>防滑徒步鞋</span><span>饮用水 1.5 L</span><span>自备路餐</span><span>雨具</span></div><div class="notice">山路有湿滑和碎石路段，请结合自身情况决定参加。遇恶劣天气，发起人会在活动通知中说明安排。</div><button class="text-btn" data-sheet="rules">查看报名与退出说明 →</button><p class="source">活动与路线数值为演示内容，不是实际邀约。</p></div>`;bottom.innerHTML=`<div class="sticky-action"><div class="summary"><b>${submitted?'待审核':'还可报名'}</b>${submitted?'请等待发起人处理':'需发起人审核'}</div><button class="primary" data-go="signup">${submitted?'查看我的报名':'报名同行'}</button></div>`}
function signup(){if(submitted){app.innerHTML=`<div class="pad">${back('detail','活动详情')}<div class="result"><div class="round">${icon('check')}</div><h2>报名已提交</h2><span class="badge amber">等待发起人审核</span><p>审核通过后，你会在活动中看到最新状态。<br>出行安排也会在这里更新。</p><button class="secondary" data-go="detail">返回活动</button></div><div class="notice">演示提交仅保留在当前页面内存中，刷新后恢复。</div></div>`;bottom.innerHTML='';return}app.innerHTML=`<div class="pad">${back('detail','活动详情')}<h2 class="page-title" style="margin-top:17px">一起同行</h2><p class="sub">龙泉山轻徒步 · 10 月 31 日</p><div class="task-strip">本场活动需要审核，提交后请等待发起人确认。</div><form id="signup-form"><div class="form-group"><h3>你的信息</h3><label class="field">姓名<input name="name" required maxlength="20" value="林同学" autocomplete="off"></label><label class="field">联系电话<input name="phone" required inputmode="tel" pattern="1[0-9]{10}" placeholder="请填写 11 位手机号" autocomplete="off"></label></div><div class="form-group"><h3>怎么出发</h3><label class="field">出行方式<select name="trip"><option value="shared">需要拼车</option><option value="self">自行前往</option></select></label><label class="field">集合点<select name="pickup"><option>龙泉驿地铁站 A 口 · 08:00</option><option>山脚集合点 · 09:00</option></select></label></div><div class="form-group"><h3>紧急联系人</h3><p class="sub" style="margin-top:7px">请填写本次不同行的亲友。</p><label class="field">联系人姓名<input name="emergency" required maxlength="20" autocomplete="off"></label><label class="field">联系人电话<input name="emergencyPhone" required pattern="1[0-9]{10}" inputmode="tel" autocomplete="off"></label></div><label class="check"><input type="checkbox" required name="consent"><span>我已阅读活动安排与风险说明，并同意将报名信息用于本次活动组织。</span></label><p class="source">这是交互演示，请使用虚构信息。不会发送或保存联系人数据。</p></form></div>`;bottom.innerHTML=`<div class="sticky-action"><button class="primary" type="submit" form="signup-form">提交报名</button></div>`;document.querySelector('#signup-form').addEventListener('submit',e=>{e.preventDefault();submitted=true;render()})}
function roster(){app.innerHTML=`<div class="pad">${back('home','活动')}<div class="topline" style="margin-top:13px"><div><span class="sub">青城后山 · 林间慢行</span><h2 class="page-title">同行名单</h2></div><span class="badge neutral">发起人</span></div><div class="stats" style="padding-top:0"><div><b>${count('confirmed')}</b><span>已确认</span></div><div><b>${count('pending')}</b><span>待审核</span></div><div><b>${count('waitlist')}</b><span>候补</span></div></div><div class="task-strip">${count('pending')?`还有 ${count('pending')} 位伙伴等待审核，点开姓名查看报名资料。`:'待审核名单已处理完，可以继续查看出行安排。'}</div><label class="search">${icon('search')}<input id="search" placeholder="在当前名单中搜索姓名" value="${escapeAttr(query)}" aria-label="搜索姓名"></label><div class="filters">${[['pending','待审核'],['confirmed','已确认'],['waitlist','候补'],['all','全部']].map(([id,s])=>`<button data-filter="${id}" class="${filter===id?'on':''}">${s}${id==='all'?'':' '+count(id)}</button>`).join('')}</div><div class="roster-label"><span>姓名 / 出行方式</span><span>报名状态</span></div><div id="person-list"></div><p class="source">演示身份：发起人。资料与操作在正式产品中仍受服务端授权控制。</p></div>`;bottom.innerHTML=`<div class="sticky-action"><button class="secondary" style="width:100%" data-sheet="transport">查看出行安排 ${icon('arrow')}</button></div>`;list();document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;list()})}
function list(){const rows=people.filter(p=>(filter==='all'||p.status===filter)&&p.name.includes(query));document.querySelector('#person-list').innerHTML=rows.length?rows.map(p=>`<button class="person" data-person="${people.indexOf(p)}"><span class="avatar">${p.name.slice(-1)}</span><span class="grow"><strong>${p.name}</strong><span class="tiny">${p.trip}</span></span><span class="status ${p.status}">${{pending:'待审核',confirmed:'已确认',waitlist:'候补'}[p.status]}</span></button>`).join(''):'<div class="empty">没有匹配的伙伴<br><button class="text-btn" data-clear="1">清除搜索并查看全部</button></div>'}
const weatherSets=[[[12,0,8],[16,0,10],[18,.4,13],[14,.8,11]],[[11,.2,7],[14,.6,9],[15,1.2,12],[12,.3,8]],[[10,0,6],[15,0,8],[17,0,9],[13,0,7]]];
function weather(){let rows=weatherSets[weatherDay],r=rows[hour];app.innerHTML=`<header class="weather-head">${back('detail','活动详情')}<span class="sub">龙泉山轻徒步 / 路线节点</span><h2>山脊观景点</h2><span class="tiny">海拔暂无可信数据</span><div class="weather-now"><div><b>${r[0]}°</b><span style="font-size:13px;margin-left:12px">${r[1]?'有降水':'多云'}</span></div>${icon('sun')}</div><p class="tiny" style="margin:10px 0">${['10 月 31 日','11 月 1 日','11 月 2 日'][weatherDay]} · ${['08:00','11:00','14:00','17:00'][hour]} 的模拟预报</p><div class="weather-data"><span>风速 ${r[2]} km/h</span><span>降水 ${r[1]} mm/h</span></div><div class="days">${['10/31 周六','11/01 周日','11/02 周一'].map((d,i)=>`<button data-day="${i}" class="${i===weatherDay?'on':''}">${d}<b>${Math.min(...weatherSets[i].map(x=>x[0]))}° / ${Math.max(...weatherSets[i].map(x=>x[0]))}°</b></button>`).join('')}</div></header><div class="pad"><div class="section-title" style="margin-top:0"><h3>沿着时间看天气</h3><span class="tiny">北京时间</span></div><div class="chart"><div class="tiny">温度 °C <span style="float:right;color:#4c8798">降水 mm/h</span></div>${weatherChart(rows)}<div class="hours">${['08:00','11:00','14:00','17:00'].map((h,i)=>`<button data-hour="${i}" class="${i===hour?'on':''}">${h}</button>`).join('')}</div><div class="readout"><div><b>${r[0]}°C</b><span>温度</span></div><div><b>${r[1]} mm/h</b><span>降水</span></div><div><b>${r[2]} km/h</b><span>风速</span></div></div></div><div class="section-title"><h3>天相与观景</h3><span class="badge neutral">资料不完整</span></div><div class="notice"><b style="color:var(--ink)">云海 · 暂时无法判断</b><br>此节点缺少可信海拔，无法判断你与云层的相对位置。</div><button class="text-btn" data-sheet="evidence">为什么不能只看云量？ →</button><p class="source">原型模拟天气 · 非实时预报<br>此处展示时间与读数联动；正式页面需接入原有天气模型和证据。</p></div>`;bottom.innerHTML=''}
function weatherChart(rows){let points=rows.map((r,i)=>`${35+i*85},${140-r[0]*5}`);return `<svg viewBox="0 0 325 185" role="img" aria-label="模拟温度与降水时间图"><defs><linearGradient id="area" x2="0" y2="1"><stop stop-color="#c9dacc" stop-opacity=".8"/><stop offset="1" stop-color="#eef3eb" stop-opacity=".1"/></linearGradient></defs>${[40,80,120,160].map(y=>`<line x1="15" x2="315" y1="${y}" y2="${y}" stroke="#e8ece5"/>`).join('')}<path d="M${points.join(' L')} L290 128 L35 128Z" fill="url(#area)"/><polyline points="${points.join(' ')}" fill="none" stroke="#54765b" stroke-width="2.2"/>${rows.map((r,i)=>`<text x="${35+i*85}" y="${129-r[0]*5}" text-anchor="middle" fill="#526b56" font-size="11">${r[0]}°</text><circle cx="${35+i*85}" cy="${140-r[0]*5}" r="${i===hour?5:3}" fill="#54765b"/><rect x="${26+i*85}" y="${169-r[1]*27}" width="18" height="${Math.max(1,r[1]*27)}" rx="3" fill="#8db9c5"/>`).join('')}<line x1="${35+hour*85}" x2="${35+hour*85}" y1="20" y2="173" stroke="#7c9384" stroke-dasharray="3 4"/><text x="3" y="180" font-size="9" fill="#647269">0</text></svg>`}
function showSheet(content){modal.innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-label="详情"><button class="round" style="float:right;width:36px;height:36px" data-close="1" aria-label="关闭">${icon('close')}</button>${content}</section>`;modal.hidden=false;modal.querySelector('button').focus()}
function personSheet(i){const p=people[i];showSheet(`<span class="sub">报名资料 · 演示</span><h2 style="margin-top:9px">${p.name}</h2><span class="badge ${p.status==='pending'?'amber':'neutral'}">${{pending:'待审核',confirmed:'已确认',waitlist:'候补'}[p.status]}</span><div class="info-row">${icon('users')}<div><b>${p.trip.split(' · ')[0]}</b><p>${p.trip.split(' · ')[1]}</p></div></div><div class="notice">已填写本人及紧急联系人信息。此原型不展示真实电话号码。</div>${p.status==='pending'?`<div class="buttons"><button class="secondary" data-close="1">暂不处理</button><button class="primary" data-approve="${i}">通过报名</button></div>`:`<div class="buttons"><button class="secondary" data-close="1">返回名单</button></div>`}`)}
const sheetTexts={create:['发起新的同行','本版先展示参与者报名与组织者审核。活动创建页尚未展开。','你可以先体验「活动详情 → 报名」，或进入「组织者名单」处理报名。'],notices:['活动通知','本版未展开通知列表。','正式产品中，通知发布、已读与外部发送分别表达，不合并为一个“已通知”状态。'],me:['我的','本版未展开个人中心。','可以从左侧切换本次设计的五个关键页面。'],later:['山谷寻秋','这是一条列表排版示例。','本版可完整进入的是「龙泉山轻徒步」，返回首页点击最近的活动即可。'],rules:['报名与退出说明','报名需发起人审核，提交不等于通过。','如计划有变，请尽早联系发起人并按活动规则退出。本工具不收取或处理活动款项。'],transport:['出行安排','审核状态与出行安排分别管理。','自行前往的伙伴不分配座位。拼车伙伴按集合点与车辆组织。本版展示名单审核，分车操作尚未展开。'],evidence:['云量不等于云海','需要知道人的位置，也需要知道云的位置。','仅有云量无法确定云层在脚下还是头顶。缺少可信海拔时，保留“无法判断”，不会把未知画成机会。']};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.go)go(d.go);else if(d.home){homeTab=d.home;home()}else if(d.filter){filter=d.filter;roster()}else if(d.clear){query='';filter='all';roster()}else if(d.person!==undefined)personSheet(+d.person);else if(d.approve!==undefined){people[+d.approve].status='confirmed';modal.hidden=true;roster();toast('已通过报名，名单数量已更新')}else if(d.close)modal.hidden=true;else if(d.sheet){let t=sheetTexts[d.sheet];showSheet(`<h2>${t[0]}</h2><p class="body-copy" style="margin-top:24px">${t[1]}</p><div class="notice">${t[2]}</div><button class="secondary" data-close="1" style="width:100%">知道了</button>`)}else if(d.day!==undefined){weatherDay=+d.day;weather()}else if(d.hour!==undefined){const scroll=app.scrollTop;hour=+d.hour;weather();app.scrollTop=scroll}});
modal.addEventListener('click',e=>{if(e.target===modal)modal.hidden=true});document.addEventListener('keydown',e=>{if(e.key==='Escape')modal.hidden=true;if(e.key==='Tab'&&!modal.hidden){let els=[...modal.querySelectorAll('button,input,select,a')];let first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});window.addEventListener('hashchange',()=>go(location.hash.slice(1)));go(notes[location.hash.slice(1)]?location.hash.slice(1):'home');
